/* codepage.c - FultaArc: names stored in a Windows code page, to UTF-8 (and passwords back). MIT.
 * Tables: cp_tables.c, generated by tools/gen_codepages.py from unicode.org's Microsoft mapping files (Unicode
 * License v3), chosen over WHATWG's after comparing both on archive names (D-007). */
#include "../core/internal.h"

extern const uint16_t fa_cp437[128], fa_cp1252[128], fa_cp866[128], fa_cp1251[128], fa_cpkoi8r[128];
extern const uint16_t fa_cp932_dbcs[24066], fa_cp936_dbcs[24066], fa_cp949_dbcs[24066], fa_cp950_dbcs[24066];
extern const uint16_t fa_cp932_single[128], fa_cp936_single[128], fa_cp949_single[128], fa_cp950_single[128];
extern const uint8_t fa_cp932_lead[128], fa_cp936_lead[128], fa_cp949_lead[128], fa_cp950_lead[128];

typedef struct dbcs { const uint16_t *pairs, *single; const uint8_t *lead; } dbcs_t;

static bool get_dbcs(fulta_arc_codepage_t cp, dbcs_t *d) {
    switch (cp) {
    case FULTA_ARC_CP_932: *d = (dbcs_t){fa_cp932_dbcs, fa_cp932_single, fa_cp932_lead}; return true;
    case FULTA_ARC_CP_936: *d = (dbcs_t){fa_cp936_dbcs, fa_cp936_single, fa_cp936_lead}; return true;
    case FULTA_ARC_CP_949: *d = (dbcs_t){fa_cp949_dbcs, fa_cp949_single, fa_cp949_lead}; return true;
    case FULTA_ARC_CP_950: *d = (dbcs_t){fa_cp950_dbcs, fa_cp950_single, fa_cp950_lead}; return true;
    default: return false;
    }
}

/* The single-byte pages: their table for bytes 0x80..0xFF, or NULL. */
static const uint16_t *sbcs_table(fulta_arc_codepage_t cp) {
    switch (cp) {
    case FULTA_ARC_CP_437: return fa_cp437;
    case FULTA_ARC_CP_1252: return fa_cp1252;
    case FULTA_ARC_CP_866: return fa_cp866;
    case FULTA_ARC_CP_1251: return fa_cp1251;
    case FULTA_ARC_CP_KOI8R: return fa_cpkoi8r;
    default: return NULL;
    }
}

static fulta_arc_err_t sbcs(fa_buf_t *b, const uint8_t *s, size_t n, const uint16_t *hi) {
    for (size_t i = 0; i < n; i++) {
        fulta_arc_err_t e = s[i] < 0x80 ? fa_buf_byte(b, s[i]) : fa_utf8_put(b, hi[s[i] - 0x80]);
        if (e) return e;
    }
    return FULTA_ARC_OK;
}

static fulta_arc_err_t dbcs_decode(fa_buf_t *b, const uint8_t *s, size_t n, const dbcs_t *d) {
    for (size_t i = 0; i < n; i++) {
        uint8_t c = s[i];
        fulta_arc_err_t e;
        if (c < 0x80) e = fa_buf_byte(b, c);
        else if (d->lead[c - 0x80] && i + 1 < n && s[i + 1] >= 0x40 && s[i + 1] <= 0xFE) {
            uint16_t u = d->pairs[(c - 0x81) * 191 + (s[i + 1] - 0x40)];
            if (u) { e = fa_utf8_put(b, u); i++; }
            else e = fa_utf8_put(b, 0xFFFD);       /* an unmapped pair: one replacement, the trail is read again */
        } else {
            uint16_t u = d->single[c - 0x80];
            e = fa_utf8_put(b, u ? u : 0xFFFD);
        }
        if (e) return e;
    }
    return FULTA_ARC_OK;
}

char *fa_codepage_to_utf8(const uint8_t *s, size_t n, fulta_arc_codepage_t cp, fulta_arc_codepage_t fallback) {
    fa_buf_t b = {0};
    if (cp == FULTA_ARC_CP_AUTO) cp = fa_utf8_valid(s, n) ? FULTA_ARC_CP_UTF8 : fallback;
    fulta_arc_err_t e;
    dbcs_t d;
    if (cp == FULTA_ARC_CP_UTF8) e = fa_utf8_valid(s, n) ? fa_buf_append(&b, s, n) : sbcs(&b, s, n, fa_cp1252);
    else if (sbcs_table(cp)) e = sbcs(&b, s, n, sbcs_table(cp));
    else if (get_dbcs(cp, &d)) e = dbcs_decode(&b, s, n, &d);
    else e = sbcs(&b, s, n, fa_cp437);
    if (!e) e = fa_buf_byte(&b, 0);
    if (e) { fa_buf_free(&b); return NULL; }
    return (char *)b.data;
}

/* UTF-8 to a code page, for passwords that an archiver stored in its code page (ALZ, old ZIP). Characters the
 * page lacks make the conversion fail (NULL). Linear search: used once per password. */
char *fa_utf8_to_codepage(const char *utf8, fulta_arc_codepage_t cp) {
    const uint8_t *s = (const uint8_t *)utf8;
    size_t n = strlen(utf8);
    fa_buf_t b = {0};
    dbcs_t d;
    bool dbcs = get_dbcs(cp, &d);
    const uint16_t *hi = sbcs_table(cp) ? sbcs_table(cp) : fa_cp437;
    for (size_t i = 0; i < n;) {
        uint32_t c = s[i];
        size_t len = 1;
        if (c >= 0xF0 && i + 3 < n) { c = ((c & 7) << 18) | ((s[i + 1] & 63u) << 12) | ((s[i + 2] & 63u) << 6) | (s[i + 3] & 63u); len = 4; }
        else if (c >= 0xE0 && i + 2 < n) { c = ((c & 15) << 12) | ((s[i + 1] & 63u) << 6) | (s[i + 2] & 63u); len = 3; }
        else if (c >= 0xC0 && i + 1 < n) { c = ((c & 31) << 6) | (s[i + 1] & 63u); len = 2; }
        i += len;
        fulta_arc_err_t e = FULTA_ARC_OK;
        bool found = false;
        if (c < 0x80) { e = fa_buf_byte(&b, (uint8_t)c); found = true; }
        else if (dbcs) {
            for (int k = 0; k < 128 && !found; k++)
                if (d.single[k] == c) { e = fa_buf_byte(&b, (uint8_t)(0x80 + k)); found = true; }
            for (size_t k = 0; k < 24066 && !found; k++)
                if (d.pairs[k] == c) {
                    uint8_t t[2] = {(uint8_t)(0x81 + k / 191), (uint8_t)(0x40 + k % 191)};
                    e = fa_buf_append(&b, t, 2);
                    found = true;
                }
        } else {
            for (int k = 0; k < 128 && !found; k++)
                if (hi[k] == c) { e = fa_buf_byte(&b, (uint8_t)(0x80 + k)); found = true; }
        }
        if (e || !found) { fa_buf_free(&b); return NULL; }
    }
    if (fa_buf_byte(&b, 0)) { fa_buf_free(&b); return NULL; }
    return (char *)b.data;
}
